;---------------------------------------------------------------------------------------------------
; SwitchInputsRead ($2D91A)
; Called from: EquipmentInit
;---------------------------------------------------------------------------------------------------
SwitchInputsRead:
        BCLR    >DriveFlags,Z,#$40                       ; bit 6: power steering pressure switch active: bit 6 of the switch bits collected from IoInputs0 (map chosen by $032D), unless P0551 is set (SwitchInputsRead)
        LDE     >IoInputs0,Z
        STE     $0A48,Z
        LDX     #$729B
        LDE     #$72BB
        BRSET   >Options032D,#$80,L2D94A                 ; bit 7: selects branches in SwitchInputsRead, SecurityStatusCalc, SciSendByte and AcClutchControl
        LDX     #$725B
        LDE     #$727B
        BRSET   >Options032D,#$20,L2D94A                 ; bit 5: A/C clutch logic on (AcClutchLogicOn); also selects the switch-input map, the VSS constants and the speed control lamp
        LDX     #$721B
        LDE     #$723B
L2D94A:
        JSR     CollectBits
        STAA    <Scratch0,Z
        XGEX
        JSR     CollectBits
        STAA    <Scratch1,Z
        LDE     >Scratch0,Z
        TED
        BRCLR   >EquipmentFlags,Z,#$04,L2D980            ; bit 2: power steering pressure switch fitted (calibration bit $0331.3, or EquipmentDetect)
        BRCLR   >Options032D,#$20,L2D96E                 ; bit 5: A/C clutch logic on (AcClutchLogicOn); also selects the switch-input map, the VSS constants and the speed control lamp
        EORD    #$0040
L2D96E:
        EORD    >SwitchPolarity,Z
        BITB    #$40
        BEQ     L2D980
        BRSET   >FaultSet0F,Z,#$08,L2D980
        BSET    >DriveFlags,Z,#$40                       ; bit 6: power steering pressure switch active: bit 6 of the switch bits collected from IoInputs0 (map chosen by $032D), unless P0551 is set (SwitchInputsRead)
L2D980:
        BRCLR   >Options032D,#$20,L2D98A                 ; bit 5: A/C clutch logic on (AcClutchLogicOn); also selects the switch-input map, the VSS constants and the speed control lamp
        EORE    #$0040
L2D98A:
        TED
        STD     <Scratch0,Z
        EORD    >SwitchPolarity,Z
        ANDD    #$0DE0
        BEQ     L2D9AC
        TED
        ANDD    >SwitchPolarity,Z
        EORE    >SwitchPolarity,Z
        PSHM    E
        ANDE    >SwitchInputs,Z
        ADE
        PULM    D
L2D9AC:
        STE     >SwitchInputs,Z
        LDE     >Scratch0,Z
        STE     >SwitchPolarity,Z
        BITA    #$01
        BEQ     L2D9C0
        BSET    >BusTxRequest,Z,#$04                     ; bit 2: switch inputs changed: send them (SwitchInputsRead)
L2D9C0:
        BRCLR   >SwitchInputs,Z,#$01,L2D9DA              ; bit 0: brake switch (BrakeSwitchMonitor, idle, speed damping, purge test)
        BRCLR   >MainLoopPhaseMask,Z,#$40,L2D9DE         ; bit 6: one pass in 128 (about 1.5 s)
        LDAA    >BrakeOnTime,Z
        INCA
        BCS     L2D9DE
        STAA    >BrakeOnTime,Z
        BRA     L2D9DE
L2D9DA:
        CLR     >BrakeOnTime,Z
L2D9DE:
        RTS

