;---------------------------------------------------------------------------------------------------
; HighRpmTimerPit ($2D9F8)
; Called from: Isr_PIT
;---------------------------------------------------------------------------------------------------
HighRpmTimerPit:
        BRCLR   >CrankFlags2,Z,#$80,L2DA3A               ; bit 7: reference event seen since the last PIT check (Isr_GPT_IC1, HighRpmTimerPit)
        BRSET   >CrankFlags2,Z,#$40,L2DA3A               ; bit 6: EngineRpm reached $1900 (HighRpmTimerPit)
        LDD     >EngineRpm,Z
        CPD     #$1900
        BCS     L2DA32
        BSET    >CrankFlags2,Z,#$40                      ; bit 6: EngineRpm reached $1900 (HighRpmTimerPit)
        LDD     >HighRpmTimer,Z
        CPD     #$0E39
        BCS     L2DA22
        LDD     #$FFFF
        BRA     L2DA28
L2DA22:
        LDE     #$0012
        EMUL
L2DA28:
        STD     >HighRpmTimer,Z
        BCLR    >CrankFlags2,Z,#$02                      ; bit 1: engine rpm below $1900: HighRpmTimer counting (HighRpmTimerPit); AsdRelayCheck and others read it
        BRA     L2DA3A
L2DA32:
        INCW    >HighRpmTimer,Z
        BSET    >CrankFlags2,Z,#$02                      ; bit 1: engine rpm below $1900: HighRpmTimer counting (HighRpmTimerPit); AsdRelayCheck and others read it
L2DA3A:
        RTS

;---------------------------------------------------------------------------------------------------
; HighRpmTimerUpdate ($2DA3C)
; Called from: EquipmentInit
;---------------------------------------------------------------------------------------------------
HighRpmTimerUpdate:
        BRCLR   >CrankFlags2,Z,#$20,L2DA48               ; bit 5: vehicle speed or bus speed value high (Isr_GPT_IC3); HighRpmTimerUpdate counts
        INCW    >HighRpmTimer,Z
        BRA     L2DA62
L2DA48:
        BRCLR   >CrankFlags2,Z,#$10,L2DA62               ; bit 4: timer update due for HighRpmTimer (HighRpmTimerUpdate)
        LDD     >HighRpmTimer,Z
        LSRD
        LSRD
        ADDD    >HighRpmTimer,Z
        STD     >HighRpmTimer,Z
        BCLR    >CrankFlags2,Z,#$10                      ; bit 4: timer update due for HighRpmTimer (HighRpmTimerUpdate)
L2DA62:
        BRCLR   >CrankFlags2,Z,#$08,L2DA6E               ; bit 3: VSS period long ($07D0 or more) not seen (Isr_GPT_IC3); HighRpmTimerUpdate counts HighRpmTimer2
        INCW    >HighRpmTimer2,Z
        BRA     L2DA88
L2DA6E:
        BRCLR   >CrankFlags2,Z,#$04,L2DA88               ; bit 2: timer update due for HighRpmTimer2 (HighRpmTimerUpdate)
        LDD     >HighRpmTimer2,Z
        LSRD
        LSRD
        ADDD    >HighRpmTimer2,Z
        STD     >HighRpmTimer2,Z
        BCLR    >CrankFlags2,Z,#$04                      ; bit 2: timer update due for HighRpmTimer2 (HighRpmTimerUpdate)
L2DA88:
        RTS

