;---------------------------------------------------------------------------------------------------
; AcControl ($2F000)
; Called from: EquipmentInit
;---------------------------------------------------------------------------------------------------
AcControl:
        JSR     AcRequestUpdate
        BRCLR   >EquipmentFlags,Z,#$10,L2F00E            ; bit 4: A/C requested (AcRequestUpdate)
        JSR     AcCutControl
L2F00E:
        RTS

;---------------------------------------------------------------------------------------------------
; AcRequestUpdate ($2F010)
; Called from: AcControl
;---------------------------------------------------------------------------------------------------
AcRequestUpdate:
        BRSET   >EquipmentFlags,Z,#$20,L2F064            ; bit 5: automatic transmission: calibration bit $032E.5, or the transmission module seen on the bus
        BRSET   >Options032E,#$40,L2F064                 ; bit 6: manual transmission: GearStateUpdate and the park/neutral monitor are skipped
        BRSET   >Options0333,#$20,L2F05A                 ; bit 5: A/C request variant (AcRequestUpdate)
        BRSET   >EquipmentFlags,Z,#$10,L2F068            ; bit 4: A/C requested (AcRequestUpdate)
        BRCLR   >EngineStateFlags,Z,#$80,L2F052          ; bit 7: engine turning: set at the first reference pulse, cleared when the engine stalls (CalcEngineRpm)
        BRSET   >BusMsgBEFlags,Z,#$40,L2F03A
        BRSET   >BusMsgBEFlags,Z,#$10,L2F052
L2F03A:
        LDAB    >MainLoopCounter,Z
        BNE     L2F068
        LDAA    $0B52,Z
        INCA
        BEQ     L2F04C
        STAA    $0B52,Z
L2F04C:
        CMPA    #$03
        BCS     L2F068
        BRA     L2F05A
L2F052:
        CLRA
        STAA    $0B52,Z
        BRA     L2F068
L2F05A:
        BSET    <EquipmentFlags,Z,#$10                   ; bit 4: A/C requested (AcRequestUpdate)
        LDAA    #$03
        STAA    $58,Z
        BRA     L2F068
L2F064:
        BCLR    <EquipmentFlags,Z,#$10                   ; bit 4: A/C requested (AcRequestUpdate)
L2F068:
        RTS

;---------------------------------------------------------------------------------------------------
; AcCutControl ($2F06A)
; Called from: AcControl
;---------------------------------------------------------------------------------------------------
AcCutControl:
        LDAA    >ActuatorTest,Z
        CMPA    #$0F
        BEQ     L2F076
        CMPA    #$14
        BNE     L2F080
L2F076:
        BRSET   >MainLoopCounter,Z,#$80,L2F190
        LBRA    L2F196
L2F080:
        BRCLR   >ThrottleState,Z,#$80,L2F196             ; bit 7: throttle open: above the learned closed position plus a margin (hysteresis when set)
        BRCLR   >DriveFlags,Z,#$20,L2F196                ; bit 5: transmission in gear (park/neutral switch), automatic only (calibration bit $032E.6 clear)
        LDAA    >CoolantTemp,Z
        CMPA    >AcCutCoolantMin
        LBCS    L2F196
        BRCLR   >SwitchInputs,Z,#$01,L2F0AA              ; bit 0: brake switch (BrakeSwitchMonitor, idle, speed damping, purge test)
        LDAA    >BrakeOnTime,Z
        CMPA    >AcCutBrakeTimeMin
        LBLS    L2F196
L2F0AA:
        BRSET   >SensorFaultFlags,Z,#$10,L2F196          ; bit 4: throttle sensor fault (ProcessThrottle, P0121 and the circuit codes)
        BRSET   >SensorFaultFlags,Z,#$20,L2F196          ; bit 5: MAP sensor fault (P0106, P0107, P0108 or P1297 set): limp MAP in use
        BRSET   >FaultSet05,Z,#$08,L2F196
        BRSET   >FaultSet0F,Z,#$04,L2F196
        BRSET   >FaultSet00,Z,#$10,L2F196
        LDAA    >Map,Z
        SUBA    >AcCutMapRef,Z
        BCS     L2F0EA
        BCLR    >AcCutFlags,Z,#$C0
        LDAB    >VehicleSpeed,Z
        CMPB    >AcCutSpeed
        BCC     L2F118
        CMPA    >AcCutMapRise
        BCS     L2F118
        LBRA    L2F196
L2F0EA:
        NEGA
        BRSET   >AcCutFlags,Z,#$80,L2F106
        BRSET   >AcCutFlags,Z,#$40,L2F110
        LDAB    >ThrottleAboveClosed,Z
        CMPB    >AcCutThrottle
        BCS     L2F10C
        BSET    >AcCutFlags,Z,#$80
L2F106:
        LDAB    >AcCutMapDrop
        BRA     L2F114
L2F10C:
        BSET    >AcCutFlags,Z,#$40
L2F110:
        LDAB    >AcCutMapDropLow
L2F114:
        CBA
        BCC     L2F196
L2F118:
        BRSET   >ControlFlags943,Z,#$80,L2F144           ; bit 7: A/C cut active (AcCutControl timer running)
        LDX     #AcThrottleUpper
        LDAA    >VehicleSpeed,Z
        JSR     Lookup2D
        CMPA    >ThrottleAboveClosed,Z
        BLS     L2F196
        LDX     #AcThrottleLower
        LDAA    >VehicleSpeed,Z
        JSR     Lookup2D
        CMPA    >ThrottleAboveClosed,Z
        BHI     L2F196
        BRA     L2F1A2
L2F144:
        LDX     #AcThrottleUpperSet
        LDAA    >VehicleSpeed,Z
        JSR     Lookup2D
        CMPA    >ThrottleAboveClosed,Z
        BLS     L2F196
        LDX     #AcThrottleLowerSet
        LDAA    >VehicleSpeed,Z
        JSR     Lookup2D
        CMPA    >ThrottleAboveClosed,Z
        BHI     L2F196
        LDAA    >AcCutTimer,Z
        BEQ     L2F178
        DECA
        STAA    >AcCutTimer,Z
        BEQ     L2F190
        BRA     L2F1A2
L2F178:
        LDAB    >AcCutDelay
        LDAA    >VehicleSpeed,Z
        CMPA    >AcCutSpeed
        BCC     L2F18A
        LDAB    >AcCutDelayLow
L2F18A:
        STAB    >AcCutTimer,Z
        BNE     L2F1A2
L2F190:
        BCLR    >ControlFlags943,Z,#$80                  ; bit 7: A/C cut active (AcCutControl timer running)
        BRA     L2F1A2
L2F196:
        BSET    >ControlFlags943,Z,#$80                  ; bit 7: A/C cut active (AcCutControl timer running)
        BCLR    >AcCutFlags,Z,#$C0
        CLR     >AcCutTimer,Z
L2F1A2:
        LDAA    >MainLoopCounter,Z
        ANDA    >AcCutMapRefMask
        BNE     L2F1B4
        LDAA    >Map,Z
        STAA    >AcCutMapRef,Z
L2F1B4:
